ActiveCompanies = {
	init: async function (app, container) { 
		var data = await api.get("B2B/Bucket/ClientRollout()?system=" + app.Config.B2B.SourceSystem + "&perspectiveKey=Creditor&$top=12");
        ActiveCompanies.initActiveCompanies(app, container, data.value.reverse());
	},

	initChart: function(args, element) {
		var chart = new Chart(element, args);
		chart.init();
		return chart;
	},

	initActiveCompanies: function(app, container, data) {
        var args = {
            showLegend: true,
            series: [ 
				{ 
					name: "[resource_displayname[supplier]] [resource_displayname[count]]", 
					data: data.map(i => i.Count),
					opacity: 1,
					markers: { visible: true, background: '#ffffff', size: 4, opacity: 0.5 },
				}
			],
            categories: data.map(i => i.Name),
            max: data.map(i => i.Count).sort((a,b) => b - a)[0],
            type: "area"
        };
        console.log({ component: "ActiveCompanies", data: data, args: args });
        return ActiveCompanies.initChart(args, $("[name=activeCompanies]", container));
	}
};
